#!/usr/bin/env python3

import logging
import os
import subprocess
from pathlib import Path

from .registry import register_command

# Template ~/.gitignore — giữ nguyên nội dung từ src/var/lib/git.sh (đã xoá).
# Bash dùng `core.excludesfile ~/.gitignore` cho global ignore; Python trước
# 5.8.7 không sinh file này nên `git:configure` thiếu một nửa chức năng.
GITIGNORE_TEMPLATE = """\
.idea/*
### Node template
# Logs
logs
*.log
npm-debug.log*

# Runtime data
pids
*.pid
*.seed
*.pid.lock

# Directory for instrumented libs generated by jscoverage/JSCover
lib-cov

# Coverage directory used by tools like istanbul
coverage

# nyc test coverage
.nyc_output

# Grunt intermediate storage (http://gruntjs.com/creating-plugins#storing-task-files)
.grunt

# node-waf configuration
.lock-wscript

# Compiled binary addons (http://nodejs.org/api/addons.html)
build/Release

# Dependency directories
node_modules
jspm_packages

# Optional npm cache directory
.npm

# Optional eslint cache
.eslintcache

# Optional REPL history
.node_repl_history

# Output of 'npm pack'
*.tgz

# Yarn Integrity file
.yarn-integrity

### Example user template

# IntelliJ project files
.idea
*.iml
out
gen
### Go template
# Compiled Object files, Static and Dynamic libs (Shared Objects)
*.o
*.a
*.so

# Folders
_obj
_test

# Architecture specific extensions/prefixes
*.[568vq]
[568vq].out

*.cgo1.go
*.cgo2.go
_cgo_defun.c
_cgo_gotypes.go
_cgo_export.*

_testmain.go

*.exe
*.test
*.prof

# Output of the go coverage tool, specifically when used with LiteIDE
*.out

# external packages folder
vendor/
### GitBook template
# Node rules:
## Grunt intermediate storage (http://gruntjs.com/creating-plugins#storing-task-files)
.grunt

## Dependency directory
## Commenting this out is preferred by some people, see
## https://docs.npmjs.com/misc/faq#should-i-check-my-node_modules-folder-into-git
node_modules

# Book build output
_book

# eBook build output
*.epub
*.mobi
*.pdf
"""


def _run_git(*args, check=True):
    try:
        result = subprocess.run(
            ["git"] + list(args),
            capture_output=True,
            text=True,
            check=check,
        )
        return result
    except subprocess.CalledProcessError as e:
        logging.error(f"Git error: {e.stderr}")
        return None


def _write_global_gitignore():
    """Ghi ~/.gitignore từ template và set core.excludesfile (bash parity)."""
    target = Path.home() / ".gitignore"
    try:
        target.write_text(GITIGNORE_TEMPLATE, encoding="utf-8")
        os.chmod(target, 0o644)
    except OSError as e:
        logging.error("Không ghi được %s: %s", target, e)
        return None

    _run_git("config", "--global", "core.excludesfile", str(target))
    return target


@register_command
def d_git_configure(args=None):
    """
    Cấu hình git cho dự án (user, email, hooks).
    Usage: ductn git:configure [--global]
    """
    is_global = args and "--global" in args

    flag = "--global" if is_global else "--local"

    # Setup user config
    name = os.getenv("GIT_AUTHOR_NAME", "")
    email = os.getenv("GIT_AUTHOR_EMAIL", "")

    if name:
        _run_git("config", flag, "user.name", name)
    if email:
        _run_git("config", flag, "user.email", email)

    # Setup default branch name
    _run_git("config", flag, "init.defaultBranch", "main")

    # Setup push default
    _run_git("config", flag, "push.default", "simple")

    # --- Phần salvage từ src/var/lib/git.sh (xoá ở 5.8.7) ---
    # Chỉ áp dụng cho --global, đúng như bash gốc.
    if is_global:
        # file mode: repo trên filesystem không hỗ trợ mode (NAS, SMB, WSL).
        _run_git("config", "--global", "core.fileMode", "false")
        # line endings: ép LF, tránh CRLF từ Windows.
        _run_git("config", "--global", "core.autocrlf", "false")
        _run_git("config", "--global", "core.eol", "lf")
        # Tắt auto gc: tránh git tự repack giữa lúc đang thao tác.
        _run_git("config", "--global", "gc.auto", "0")
        # Cho phép push vào repo không phải bare (deploy bằng git push).
        _run_git("config", "--global", "receive.denyCurrentBranch", "updateInstead")
        # Sinh ~/.gitignore và trỏ core.excludesfile vào đó.
        _write_global_gitignore()

    logging.info("Git đã được cấu hình")


@register_command
def d_git_detrack(args=None):
    """
    Bỏ đánh dấu assume-unchanged để git theo dõi lại file.
    Usage: ductn git:detrack <file>

    Lưu ý: đây là bản sửa của 5.8.7. Trước đó Python chạy
    `git rm --cached` (xoá file khỏi index) — KHÁC hoàn toàn với bash gốc
    vốn chạy `git update-index --no-assume-unchanged`.
    """
    if not args:
        logging.error("Usage: ductn git:detrack <file>")
        return

    for filepath in args if isinstance(args, list) else [args]:
        result = _run_git("update-index", "--no-assume-unchanged", filepath)
        if result is not None:
            logging.info(f"Đã detrack {filepath}")
        else:
            logging.error(f"Không thể detrack {filepath}")


@register_command
def d_git_untrack(args=None):
    """
    Đánh dấu assume-unchanged để git bỏ qua thay đổi của file.
    Usage: ductn git:untrack <file>

    File vẫn nằm trong index và trên đĩa; chỉ các thay đổi sau đó bị bỏ qua.
    Bản sửa của 5.8.7 — trước đó alias sang `git rm --cached`.
    """
    if not args:
        logging.error("Usage: ductn git:untrack <file>")
        return

    for filepath in args if isinstance(args, list) else [args]:
        result = _run_git("update-index", "--assume-unchanged", filepath)
        if result is not None:
            logging.info(f"Đã untrack {filepath}")
        else:
            logging.error(f"Không thể untrack {filepath}")


@register_command
def d_git_viewuntrack():
    """
    Hiển thị các file đang được đánh dấu assume-unchanged.
    Bash gốc: `git ls-files -v | grep "^[[:lower:]]"` — chữ thường = bị assume.

    Định dạng mỗi dòng của `git ls-files -v` là ``<tag><space><path>``.
    """
    result = _run_git("ls-files", "-v")
    if not result or not result.stdout:
        return

    for line in result.stdout.splitlines():
        # Chỉ nhận dòng đúng định dạng "<tag> <path>" với tag là chữ thường.
        if len(line) > 2 and line[0].islower() and line[1] == " ":
            print(line[2:])


@register_command
def d_git_tag_cleanup(args=None):
    """
    Dọn dẹp git tags cũ.
    Usage: ductn git:tag:cleanup [số_tag_giữ_lại]

    Bash gốc: giữ N tag đầu (mặc định 5), xoá phần còn lại trên origin.
    Python trước 5.8.7 chỉ in danh sách, KHÔNG xoá gì — nay khớp bash.
    """
    keep = 5
    if args:
        first = args[0] if isinstance(args, list) else args
        try:
            keep = int(first)
        except (TypeError, ValueError):
            logging.error("Số tag giữ lại phải là số nguyên, nhận: %s", first)
            return

    result = _run_git("tag")
    if not result or not result.stdout.strip():
        logging.info("Không có tag nào")
        return

    tags = result.stdout.strip().splitlines()
    stale = tags[keep:]
    if not stale:
        logging.info("Chỉ có %d tag, không cần dọn (giữ %d)", len(tags), keep)
        return

    logging.info("Xoá %d tag cũ trên origin: %s", len(stale), ", ".join(stale))
    for tag in stale:
        _run_git("push", "--delete", "origin", tag, check=False)

    _run_git("fetch", "--prune", "origin", "+refs/tags/*:refs/tags/*", check=False)
